import React from "react";
import { Link, useNavigate } from "react-router-dom";
import "./../../css/Consultation.css";

class Consultation extends React.Component {
  state = {
    currentStep: 0,
    stepStack: [0],

    entryPath: null,
    directService: null,

    concerns: [],
    desc: "",
    photoAdded: false,
    photo: null,

    specMode: "any",
    specName: null,

    dateNum: "۱۷",
    dateDay: "سه‌شنبه",
    dateMon: "شهریور",

    anyTime: false,
    time: "۱۵:۳۰",

    name: "",
    phone: "",
    notes: "",
  };

  labels = {
    0: "",
    1: "انتخاب دغدغه",
    2: "توضیح نیاز",
    3: "انتخاب متخصص",
    4: "زمان مدنظر",
    5: "اطلاعات شما",
    6: "",
  };

  goTo = (step, push = true) => {
    this.setState((prevState) => ({
      currentStep: step,
      stepStack: push
        ? [...prevState.stepStack, step]
        : prevState.stepStack,
    }));
  };

  goBack = () => {
    this.setState((prevState) => {
      if (prevState.stepStack.length > 1) {
        const newStack = [...prevState.stepStack];
        newStack.pop();

        return {
          currentStep: newStack[newStack.length - 1],
          stepStack: newStack,
        };
      }

      this.props.navigate("/service-detail");

      return null;
    });
  };

  selectEntry = (which) => {
    this.setState({
      entryPath: which,
      directService: which === "direct" ? this.state.directService : null,
    });

    if (which === "guide") {
      this.goTo(1);
    }
  };

  selectDirectService = (service) => {
    this.setState({
      directService: service,
    });

    setTimeout(() => {
      this.goTo(3);
    }, 150);
  };

  toggleConcern = (concern) => {
    this.setState((prevState) => {
      const exists = prevState.concerns.includes(concern);

      return {
        concerns: exists
          ? prevState.concerns.filter((item) => item !== concern)
          : [...prevState.concerns, concern],
      };
    });
  };

  handleDescription = (e) => {
    this.setState({
      desc: e.target.value,
    });
  };

  toggleUpload = () => {
    this.setState((prevState) => ({
      photoAdded: !prevState.photoAdded,
      photo: null,
    }));
  };

  selectSpecMode = (mode) => {
    this.setState({
      specMode: mode,
      specName: mode === "any" ? null : this.state.specName,
    });
  };

  selectSpecialist = (name) => {
    this.setState({
      specName: name,
      specMode: "choose",
    });
  };

  toggleAnyTime = () => {
    this.setState((prevState) => ({
      anyTime: !prevState.anyTime,
    }));
  };

  selectDate = (day, num, mon) => {
    this.setState({
      dateDay: day,
      dateNum: num,
      dateMon: mon,
    });
  };

  selectTime = (time) => {
    this.setState({
      time,
    });
  };

  handleInput = (field, value) => {
    this.setState({
      [field]: value,
    });
  };

  bookDirect = (e) => {
    e.preventDefault();
    this.goTo(4);
  };

  getTopic = () => {
    const { concerns, directService } = this.state;

    if (concerns.length) {
      return concerns.join("، ");
    }

    return directService || "مشخص نشده";
  };

  getSpecialist = () => {
    const { specMode, specName } = this.state;

    if (specMode === "choose" && specName) {
      return specName;
    }

    return "هر متخصص موجود";
  };

  getTime = () => {
    const {
      anyTime,
      dateDay,
      dateNum,
      dateMon,
      time,
    } = this.state;

    if (anyTime) {
      return "هر زمان خالی، نزدیک‌ترین نوبت";
    }

    return `${dateDay} ${dateNum} ${dateMon}، ساعت ${time}`;
  };

  getFooterText = () => {
    const { currentStep, concerns, desc, photoAdded } = this.state;

    if (currentStep === 1) {
      return concerns.length ? "ادامه" : "رد شو برای الان";
    }

    if (currentStep === 2) {
      return desc || photoAdded ? "ادامه" : "رد شو برای الان";
    }

    if (currentStep === 3) {
      return "ادامه";
    }

    if (currentStep === 4) {
      return "ادامه";
    }

    if (currentStep === 5) {
      return "درخواست مشاوره";
    }

    return "";
  };

  handleFooterClick = () => {
    const { currentStep } = this.state;

    if (currentStep === 1) {
      this.goTo(2);
    } else if (currentStep === 2) {
      this.goTo(3);
    } else if (currentStep === 3) {
      this.goTo(4);
    } else if (currentStep === 4) {
      this.goTo(5);
    } else if (currentStep === 5) {
      this.goTo(6);
    }
  };

  renderIcon = (type) => {
    const icons = {
      question: (
        <>
          <circle cx="12" cy="12" r="10" />
          <path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 1.5-2.5 2-2.5 3.5" />
          <path d="M12 17h.01" />
        </>
      ),
      check: (
        <>
